{
  "meta": {
    "name": "E-commerce Store",
    "description": "An online store enabling customers to browse products, place and track orders, while admins manage the product catalog and view sales, and premium sellers receive featured listings."
  },
  "entities": [
    {
      "name": "Product",
      "ownable": false,
      "fields": [
        {
          "name": "name",
          "type": "string",
          "required": true
        },
        {
          "name": "description",
          "type": "text"
        },
        {
          "name": "price",
          "type": "number",
          "required": true
        },
        {
          "name": "stockQuantity",
          "type": "integer",
          "required": true,
          "default": 0
        },
        {
          "name": "imageUrl",
          "type": "url"
        },
        {
          "name": "category",
          "type": "string"
        },
        {
          "name": "isFeatured",
          "type": "boolean",
          "default": false
        }
      ],
      "relations": [
        {
          "name": "seller",
          "kind": "manyToOne",
          "target": "Seller",
          "required": true
        }
      ]
    },
    {
      "name": "Order",
      "ownable": true,
      "fields": [
        {
          "name": "orderNumber",
          "type": "string",
          "required": true,
          "unique": true
        },
        {
          "name": "orderDate",
          "type": "datetime",
          "required": true,
          "default": "now()"
        },
        {
          "name": "status",
          "type": "enum",
          "required": true,
          "enumValues": [
            "pending",
            "processing",
            "shipped",
            "delivered",
            "cancelled"
          ],
          "default": "pending"
        },
        {
          "name": "totalAmount",
          "type": "number",
          "required": true
        },
        {
          "name": "shippingAddress",
          "type": "text",
          "required": true
        },
        {
          "name": "paymentStatus",
          "type": "enum",
          "required": true,
          "enumValues": [
            "unpaid",
            "paid",
            "refunded"
          ],
          "default": "unpaid"
        }
      ],
      "relations": [
        {
          "name": "customer",
          "kind": "manyToOne",
          "target": "User",
          "required": true
        },
        {
          "name": "items",
          "kind": "oneToMany",
          "target": "OrderItem",
          "required": true
        }
      ]
    },
    {
      "name": "Seller",
      "ownable": false,
      "fields": [
        {
          "name": "name",
          "type": "string",
          "required": true
        },
        {
          "name": "contactEmail",
          "type": "email",
          "required": true
        },
        {
          "name": "isPremium",
          "type": "boolean",
          "default": false
        }
      ],
      "relations": [
        {
          "name": "products",
          "kind": "oneToMany",
          "target": "Product"
        },
        {
          "name": "orders",
          "kind": "oneToMany",
          "target": "Order"
        }
      ]
    },
    {
      "name": "OrderItem",
      "ownable": false,
      "fields": [
        {
          "name": "quantity",
          "type": "integer",
          "required": true
        },
        {
          "name": "priceAtPurchase",
          "type": "number",
          "required": true
        }
      ],
      "relations": [
        {
          "name": "order",
          "kind": "manyToOne",
          "target": "Order",
          "required": true
        },
        {
          "name": "product",
          "kind": "manyToOne",
          "target": "Product",
          "required": true
        }
      ]
    }
  ],
  "roles": [
    {
      "name": "customer",
      "description": "Browses products, places and tracks orders.",
      "isDefault": true
    },
    {
      "name": "admin",
      "description": "Manages product catalog and sees sales."
    },
    {
      "name": "seller",
      "description": "Manages their own products."
    }
  ],
  "permissions": [
    {
      "role": "customer",
      "entity": "Product",
      "actions": ["read"],
      "scope": "all"
    },
    {
      "role": "customer",
      "entity": "Order",
      "actions": ["create", "read", "update"],
      "scope": "own"
    },
    {
      "role": "customer",
      "entity": "OrderItem",
      "actions": ["read"],
      "scope": "all"
    },
    {
      "role": "admin",
      "entity": "Product",
      "actions": ["create", "read", "update", "delete"],
      "scope": "all"
    },
    {
      "role": "admin",
      "entity": "Order",
      "actions": ["read", "update"],
      "scope": "all"
    },
    {
      "role": "admin",
      "entity": "Seller",
      "actions": ["read", "update"],
      "scope": "all"
    },
    {
      "role": "seller",
      "entity": "Product",
      "actions": ["create", "read", "update"],
      "scope": "own"
    },
    {
      "role": "seller",
      "entity": "Order",
      "actions": ["read"],
      "scope": "all"
    }
  ],
  "pages": [
    {
      "name": "Products",
      "route": "/products",
      "type": "list",
      "entity": "Product",
      "access": ["customer", "admin", "seller"]
    },
    {
      "name": "Product Detail",
      "route": "/products/:id",
      "type": "detail",
      "entity": "Product",
      "access": ["customer", "admin", "seller"]
    },
    {
      "name": "New Product",
      "route": "/products/new",
      "type": "form",
      "entity": "Product",
      "access": ["admin", "seller"]
    },
    {
      "name": "Edit Product",
      "route": "/products/:id/edit",
      "type": "form",
      "entity": "Product",
      "access": ["admin", "seller"]
    },
    {
      "name": "My Orders",
      "route": "/my-orders",
      "type": "list",
      "entity": "Order",
      "access": ["customer"]
    },
    {
      "name": "Order Detail",
      "route": "/my-orders/:id",
      "type": "detail",
      "entity": "Order",
      "access": ["customer", "admin"]
    },
    {
      "name": "Place Order",
      "route": "/checkout",
      "type": "form",
      "entity": "Order",
      "access": ["customer"],
      "requiresPlan": "premium"
    },
    {
      "name": "Sales Dashboard",
      "route": "/sales",
      "type": "dashboard",
      "access": ["admin"],
      "widgets": [
        {
          "type": "stat",
          "label": "Total Sales",
          "entity": "Order",
          "metric": "sum",
          "field": "totalAmount"
        },
        {
          "type": "chart",
          "label": "Sales Over Time",
          "entity": "Order",
          "metric": "sum",
          "field": "totalAmount"
        }
      ]
    },
    {
      "name": "Sellers",
      "route": "/sellers",
      "type": "list",
      "entity": "Seller",
      "access": ["admin"]
    },
    {
      "name": "Featured Products",
      "route": "/featured",
      "type": "list",
      "entity": "Product",
      "access": ["customer"],
      "filters": {
        "isFeatured": true
      },
      "requiresPlan": "premium"
    }
  ],
  "plans": [
    {
      "name": "free",
      "isDefault": true
    },
    {
      "name": "premium",
      "price": 10,
      "interval": "month",
      "features": [
        "featuredListings",
        "prioritySupport"
      ]
    }
  ],
  "businessRules": [
    {
      "type": "plan_gate",
      "id": "premiumSellerFeatures",
      "requiresPlan": "premium",
      "gates": {
        "pages": [
          "Featured Products"
        ],
        "features": [
          "featuredListings"
        ]
      }
    },
    {
      "type": "ownership",
      "id": "orderOwnership",
      "entity": "Order"
    },
    {
      "type": "ownership",
      "id": "productOwnership",
      "entity": "Product"
    },
    {
      "type": "ownership",
      "id": "orderItemOwnership",
      "entity": "OrderItem"
    }
  ],
  "auth": {
    "strategy": "email_password",
    "requireAuth": true
  }
}
